// Individual identities for completion lot 2. Named moves and role actions are
// authored per roster ID; these helpers share only the engine action format.
// Timings, power and support percentages are gameplay adaptations, never claims
// of source-game frame data or supernatural powers for real performers.
const record = (universe, sourceWork, sourceReference, special, identityBasis = 'canonical-role') => ({
  universe, sourceWork, sourceReference, identityBasis,
  canonicalVerified: false, networkVerified: false, gameplayAdaptation: true, special
});
const move = (name, type, dmg, color, targeting) => ({
  name, type, dmg, color, animationDuration: 1.1, hitAt: 0.45, targeting
});
const melee = (name, color, dmg = 4.2, options = {}) => move(name, 'melee', dmg, color,
  { effect: 'damage', targetSide: 'enemy', shape: 'single', delivery: 'melee', range: 170, ...options });
const shot = (name, color, dmg = 4.2, options = {}) => move(name, 'projectile', dmg, color,
  { effect: 'damage', targetSide: 'enemy', shape: 'single', delivery: 'projectile', range: 640, ...options });
const beam = (name, color, dmg = 4.4, options = {}) => move(name, 'beam', dmg, color,
  { effect: 'damage', targetSide: 'enemy', shape: 'line', delivery: 'beam', range: 640, lineWidth: 42, ...options });
const area = (name, color, dmg = 4.3, options = {}) => move(name, 'area', dmg, color,
  { effect: 'damage', targetSide: 'enemy', shape: 'area', delivery: 'area', range: 500, areaRadius: 140, ...options });
const guard = (name, color, options = {}) => move(name, 'guard', 0, color,
  { effect: 'guard', targetSide: 'ally', shape: 'group', delivery: 'support', range: 760, duration: 4, reduce: 0.5, ...options });
const buff = (name, color, options = {}) => move(name, 'buff', 0, color,
  { effect: 'buff', targetSide: 'ally', shape: 'group', delivery: 'support', range: 760, duration: 4, buffMultiplier: 1.2, ...options });
const heal = (name, color, options = {}) => move(name, 'heal', 0, color,
  { effect: 'heal', targetSide: 'ally', shape: 'group', delivery: 'support', range: 760, healRatio: 0.3, ...options });
const cleanse = (name, color, options = {}) => move(name, 'cleanse', 0, color,
  { effect: 'cleanse', targetSide: 'ally', shape: 'group', delivery: 'support', range: 760, cleanses: true, ...options });

